import styled from '@emotion/styled';

export const StyledResponsiveWarning = styled.div({
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  height: '80vh',
  flexDirection: 'column',
  padding: '24px',
  '.empty-state-img': {
    marginBottom: '24px',
  },
});
